package com.oms.inventory;

import com.oms.inventory.service.impl.OrderVirtualOutboundService;
import com.oms.inventory.service.impl.OrderWarehouseAllocationService;
import com.oms.inventory.service.impl.OrderStockService;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class OrderVirtualOutboundTest {
    OrderStockTest fixture=new OrderStockTest();OrderVirtualOutboundService service;
    @BeforeAll static void start(){OrderStockTest.start();}
    @AfterAll static void stop(){OrderStockTest.stop();}
    @BeforeEach void seed(){fixture.clear();service=OrderStockTest.context.getBean(OrderVirtualOutboundService.class);}
    Map<String,Object> row(Object...pairs){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)r.put(pairs[i].toString(),pairs[i+1]);return r;}
    long n(String sql){return fixture.n(sql);}
    List<Map<String,Object>> allocate(int quantity,boolean locked){if(locked)fixture.locked30();else fixture.seed(100,20);fixture.execute("register",fixture.command("12345",quantity,true));fixture.execute("reserve",fixture.command("12345",quantity,true));Map<String,Object> command=row("channel_id",1,"platform_tid","12345","allow_multi",0,"allow_partial",1,"allow_split_sku",0,"lines",Arrays.asList(row("platform_oid","12345","sku_sn","A","quantity",quantity)),"stores",Arrays.asList(row("store_code","W1","owner_code","O1","real_store_code","R1","real_store_name","warehouse")));return OrderStockTest.context.getBean(OrderWarehouseAllocationService.class).allocate("VERIFY",command);}
    Map<String,Object> command(String request,List<Map<String,Object>> receipts,long...quantities){List<Map<String,Object>> lines=new ArrayList<>();long total=0;for(int i=0;i<receipts.size();i++){if(quantities[i]==0)continue;Map<String,Object> receipt=receipts.get(i),line=new LinkedHashMap<>();for(String field:Arrays.asList("id","sku_sn","platform_oid","store_code","source_type","owner_code","real_store_code","batch_id","stock_source_id"))line.put(field,receipt.get(field));line.put("allocation_id",receipt.get("id"));line.put("outbound_before",receipt.get("outbound_quantity"));line.put("quantity",quantities[i]);lines.add(line);total+=quantities[i];}return row("request_id",request,"shipment_sn","FH_VIRTUAL_TEST","channel_id",1,"platform_tid","12345","operator_name","tester","quantity",total,"lines",lines);}
    List<Map<String,Object>> receipts(){return OrderStockTest.context.getBean(OrderWarehouseAllocationService.class).receipts("VERIFY",1,"12345");}
    @Test void partialThenFullConsumesPhysicalStockAndDoesNotReturnQuota(){List<Map<String,Object>> receipts=allocate(10,false);Map<String,Object> first=command("VIRTUAL_REQUEST_0001",receipts,4);Map<String,Object> reply=service.outbound("VERIFY",first);assertEquals("COMPLETED",reply.get("state"));assertEquals(96,n("SELECT zp_actual_number FROM wms_inventory"));assertEquals(90,n("SELECT zp_available_number FROM wms_inventory"));assertEquals(6,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(96,n("SELECT total_stock FROM oms_inventory"));assertEquals(6,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(6,n("SELECT reserved_stock FROM oms_channel_inventory"));assertEquals(16,n("SELECT quota_stock FROM oms_channel_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_channel_inventory"));assertEquals(10,n("SELECT reserved_quantity FROM oms_order_stock_demand"));assertEquals(4,n("SELECT outbound_quantity FROM oms_order_stock_demand"));assertEquals(0,OrderStockService.publicReserved(OrderStockTest.db,"VERIFY","A"));service.outbound("VERIFY",first);assertEquals(1,n("SELECT COUNT(*) FROM oms_order_virtual_outbound"));service.outbound("VERIFY",command("VIRTUAL_REQUEST_0002",receipts(),6));assertEquals(90,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_channel_inventory"));assertEquals(10,n("SELECT quota_stock FROM oms_channel_inventory"));assertEquals(2,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='VIRTUAL_OUTBOUND'"));fixture.execute("reserve",fixture.command("12345",10,true));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(10,n("SELECT outbound_quantity FROM oms_order_warehouse_allocation"));}
    @Test void lockAndPublicInSameBatchProduceOneJournalAndPreserveRuleAttribution(){List<Map<String,Object>> rows=allocate(40,true);assertEquals(2,rows.size());service.outbound("VERIFY",command("VIRTUAL_REQUEST_0010",rows,30,10));assertEquals(60,n("SELECT zp_actual_number FROM wms_inventory"));assertEquals(60,n("SELECT zp_available_number FROM wms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(30,n("SELECT consumed_quantity FROM rule_stock_reservation"));assertEquals(0,n("SELECT occupied_quantity FROM rule_stock_reservation"));assertEquals(30,n("SELECT consumed_quantity FROM rule_stock_result"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='VIRTUAL_OUTBOUND'"));assertEquals(-40,n("SELECT SUM(change_quantity) FROM wms_inventory_change_history WHERE operation_type='VIRTUAL_OUTBOUND'"));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,OrderStockService.publicReserved(OrderStockTest.db,"VERIFY","A"));}
    @Test void replayMustKeepSamePayloadAndCannotCrossTenantOrOrder(){Map<String,Object> command=command("VIRTUAL_REQUEST_0020",allocate(10,false),4);assertThrows(IllegalArgumentException.class,()->service.outbound("OTHER",command));service.outbound("VERIFY",command);assertEquals("COMPLETED",service.receipt("VERIFY","VIRTUAL_REQUEST_0020").get("state"));assertEquals("MISSING",service.receipt("OTHER","VIRTUAL_REQUEST_0020").get("state"));Map<String,Object> changed=new LinkedHashMap<>(command);changed.put("shipment_sn","ANOTHER");assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",changed));assertEquals(96,n("SELECT total_stock FROM oms_inventory"));}
    @Test void excessiveStaleAndWrongBatchNeverPostAnyStock(){List<Map<String,Object>> rows=allocate(10,false);assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",command("VIRTUAL_REQUEST_0030",rows,11)));Map<String,Object> wrong=command("VIRTUAL_REQUEST_0031",rows,4);((Map<?,?>)((List<?>)wrong.get("lines")).get(0)).clear();assertThrows(RuntimeException.class,()->service.outbound("VERIFY",wrong));service.outbound("VERIFY",command("VIRTUAL_REQUEST_0032",rows,4));assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",command("VIRTUAL_REQUEST_0033",rows,4)));assertEquals(96,n("SELECT total_stock FROM oms_inventory"));assertEquals(1,n("SELECT COUNT(*) FROM oms_order_virtual_outbound"));}
    @Test void cancellationAfterPartialOutboundCannotRestoreConsumedStock(){service.outbound("VERIFY",command("VIRTUAL_REQUEST_0040",allocate(10,false),4));assertThrows(IllegalArgumentException.class,()->fixture.execute("cancel",fixture.command("12345",10,true)));assertEquals(96,n("SELECT total_stock FROM oms_inventory"));assertEquals(6,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(6,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals("RESERVED",OrderStockTest.db.queryForObject("SELECT status FROM oms_order_stock_demand",String.class));}
    @Test void concurrentSameRequestReturnsSameReceiptAndDeductsOnce() throws Exception {Map<String,Object> command=command("VIRTUAL_REQUEST_0050",allocate(10,false),10);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Map<String,Object>>> jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();return service.outbound("VERIFY",command);}));start.countDown();for(Future<Map<String,Object>> job:jobs)assertEquals("COMPLETED",job.get(20,TimeUnit.SECONDS).get("state"));}finally{pool.shutdownNow();}assertEquals(90,n("SELECT total_stock FROM oms_inventory"));assertEquals(1,n("SELECT COUNT(*) FROM oms_order_virtual_outbound"));}
    @Test void physicalBalanceFailureRollsBackAllSourceCounters(){List<Map<String,Object>> rows=allocate(10,false);OrderStockTest.db.update("UPDATE wms_inventory SET zp_actual_number=99");assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",command("VIRTUAL_REQUEST_0060",rows,4)));assertEquals(100,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,n("SELECT outbound_quantity FROM oms_order_stock_source"));assertEquals(0,n("SELECT outbound_quantity FROM oms_order_stock_demand"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_virtual_outbound"));}
    @Test void secondSourceFailureRollsBackFirstSourceAndAllJournals(){List<Map<String,Object>> rows=allocate(40,true);Map<String,Object> c=command("VIRTUAL_REQUEST_0080",rows,30,10);((Map<String,Object>)((List<?>)c.get("lines")).get(1)).put("outbound_before",1);assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",c));assertEquals(100,n("SELECT total_stock FROM oms_inventory"));assertEquals(40,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,n("SELECT consumed_quantity FROM rule_stock_reservation"));assertEquals(30,n("SELECT occupied_quantity FROM rule_stock_result"));assertEquals(0,n("SELECT SUM(outbound_quantity) FROM oms_order_warehouse_allocation"));assertEquals(0,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='VIRTUAL_OUTBOUND'"));}
    @Test void ruleReleaseAfterPartialConsumptionProtectsRemainingOrderOccupation(){List<Map<String,Object>> rows=allocate(20,true);service.outbound("VERIFY",command("VIRTUAL_REQUEST_0090",rows,10));new org.springframework.transaction.support.TransactionTemplate(OrderStockTest.context.getBean(org.springframework.transaction.PlatformTransactionManager.class)).execute(status->{Map<String,Object> result=OrderStockTest.db.queryForObject("SELECT * FROM rule_stock_result WHERE rule_id=700",com.oms.inventory.service.impl.InventoryQueryService.ROW);OrderStockTest.context.getBean(com.oms.inventory.service.impl.rule.AllocationReservationService.class).release("VERIFY",700,result,"tester");return null;});assertEquals(10,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(10,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(10,n("SELECT released_quantity FROM rule_stock_result"));service.outbound("VERIFY",command("VIRTUAL_REQUEST_0091",receipts(),10));assertEquals(80,n("SELECT total_stock FROM oms_inventory"));assertEquals(80,n("SELECT zp_available_number FROM wms_inventory"));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(20,n("SELECT consumed_quantity FROM rule_stock_result"));assertEquals("RELEASED",OrderStockTest.db.queryForObject("SELECT release_status FROM rule_stock_result",String.class));}
    @Test void warehouseConsumptionUsesSameAtomicSourcesWithSeparateReplayMode(){Map<String,Object> c=command("WO_REQUEST_TEST_0100",allocate(10,false),4);assertEquals("WMS",service.warehouseOutbound("VERIFY",c).get("source_mode"));service.warehouseOutbound("VERIFY",c);assertEquals(96,n("SELECT total_stock FROM oms_inventory"));assertEquals(4,n("SELECT outbound_quantity FROM oms_order_warehouse_allocation"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='WMS_OUTBOUND'"));assertEquals("MISSING",service.receipt("VERIFY","WO_REQUEST_TEST_0100").get("state"));assertEquals("COMPLETED",service.warehouseReceipt("VERIFY","WO_REQUEST_TEST_0100").get("state"));assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",c));assertThrows(IllegalArgumentException.class,()->service.outbound("VERIFY",command("VIRTUAL_REQUEST_0101",receipts(),2)));}
    @Test void warehouseLockAndPublicSettlementRemainAttributable(){service.warehouseOutbound("VERIFY",command("WO_REQUEST_TEST_0110",allocate(40,true),30,10));assertEquals(60,n("SELECT total_stock FROM oms_inventory"));assertEquals(30,n("SELECT consumed_quantity FROM rule_stock_reservation"));assertEquals(0,n("SELECT reserved_stock FROM oms_channel_inventory"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='WMS_OUTBOUND'"));}
    @Test void twoLinesSharingBatchRemainAttributable(){fixture.seed(100,20);com.oms.common.model.dto.OrderStockCommand c=fixture.command("12345",5,true);com.oms.common.model.dto.OrderStockCommand.Line second=new com.oms.common.model.dto.OrderStockCommand.Line();second.setPlatformOid("12346");second.setSkuSn("A");second.setQuantity(5);c.getLines().add(second);fixture.execute("register",c);fixture.execute("reserve",c);Map<String,Object> allocation=row("channel_id",1,"platform_tid","12345","allow_partial",1,"lines",Arrays.asList(row("platform_oid","12345","sku_sn","A","quantity",5),row("platform_oid","12346","sku_sn","A","quantity",5)),"stores",Arrays.asList(row("store_code","W1","owner_code","O1","real_store_code","R1","real_store_name","warehouse")));List<Map<String,Object>> rows=OrderStockTest.context.getBean(OrderWarehouseAllocationService.class).allocate("VERIFY",allocation);service.outbound("VERIFY",command("VIRTUAL_REQUEST_0070",rows,2,3));assertEquals(95,n("SELECT total_stock FROM oms_inventory"));assertEquals(5,n("SELECT SUM(outbound_quantity) FROM oms_order_stock_demand"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='VIRTUAL_OUTBOUND'"));}
}
